// measurement phase is active.  Buffer size is unchanged.
top->owner_only_i       = (owner_only && measurement_phase) ? 1 : 0;

setup_memory(a_pages);
// Repeated-scenario hygiene: enter with the owner-only measurement
// phase OFF so the reset ticks and the whole warm phase drive
// owner_only_i low.  Warm caches and already-selected requests are
// untouched.
