if (const char* v = val("owner-only")) {
    char* end = nullptr;
    const unsigned long parsed = std::strtoul(v, &end, 0);
    if (end == v || *end != '\0' || parsed > 1) {
        std::fprintf(stderr,
            "nonblock_actual_dma_test: invalid +owner-only='%s' (expected 0|1)\n", v);
        return 2;
    }
    owner_only = (parsed != 0);
